// 발행현황 CSV 주간 집계 (기준: 최근 7일, 한국시간)
const 목표건수 = 100; // ← 캠페인 목표 총량에 맞게 수정
const rows = $('CSV 파싱').all().map(i => i.json);

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const total = rows.length;
let week = 0;
const weekByClient = {};
const totalByClient = {};
for (const r of rows) {
  const c = r.client || r['client'] || '기타';
  totalByClient[c] = (totalByClient[c] || 0) + 1;
  const d = new Date(r.publishedAt || r['publishedAt']);
  if (!isNaN(d) && d >= weekAgo && d <= now) {
    week++;
    weekByClient[c] = (weekByClient[c] || 0) + 1;
  }
}
const kst = new Date(now.getTime() + 9 * 60 * 60 * 1000);
const pad = (n) => String(n).padStart(2, '0');
const ymd = `${String(kst.getUTCFullYear()).slice(2)}.${pad(kst.getUTCMonth() + 1)}.${pad(kst.getUTCDate())}`;
const wk = Object.entries(weekByClient).sort((a, b) => b[1] - a[1])
  .map(([c, n]) => `  · ${c}: ${n}개`).join('\n') || '  · (최근 7일 발행 없음)';
const tot = Object.entries(totalByClient).sort((a, b) => b[1] - a[1])
  .map(([c, n]) => `  · ${c}: ${n}개`).join('\n');

let msg = `안녕하세요. 작업 중간 보고 드립니다.\n`;
msg += `소식글 발행 ${total}/${목표건수}\n`;
msg += `${ymd} 기준 / 최근 7일 ${week}개 완료\n\n`;
msg += `[고객사별 최근 7일]\n${wk}\n\n`;
msg += `[고객사별 누적]\n${tot}`;

return [{ json: { message: msg, total, week, 목표건수 } }];
